import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './FaceAuth.css';

const FaceAuth = ({ setUser }) => {
  const [cameraActive, setCameraActive] = useState(false);
  const [scanning, setScanning] = useState(false);
  const [message, setMessage] = useState('');
  const [status, setStatus] = useState('idle'); // idle, scanning, success, error
  const [useStaticImage, setUseStaticImage] = useState(true); // Start with static image
  const [uploadedImage, setUploadedImage] = useState(null);
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const navigate = useNavigate();

  // Mock employee database
  const EMPLOYEES = [
    { id: 'E001', name: 'Admin User', role: 'admin', email: 'admin@company.com' },
    { id: 'E002', name: 'Manager User', role: 'manager', email: 'manager@company.com' },
    { id: 'E003', name: 'Employee User', role: 'employee', email: 'employee@company.com' },
  ];

  useEffect(() => {
    return () => {
      // Cleanup camera on unmount
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: 640, height: 480 }
      });
      
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setCameraActive(true);
        setMessage('Camera ready. Click "Scan Face" to authenticate.');
      }
    } catch (error) {
      setStatus('error');
      setMessage('❌ Camera access denied. Please allow camera permissions.');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      setCameraActive(false);
      streamRef.current = null;
    }
  };

  const simulateFaceRecognition = () => {
    return new Promise((resolve) => {
      // Simulate face detection delay
      setTimeout(() => {
        // Randomly select an employee (in production, this would be actual face recognition)
        const employee = EMPLOYEES[0]; // Default to admin for demo
        resolve(employee);
      }, 2000);
    });
  };

  const handleScanFace = async () => {
    if (!cameraActive && !uploadedImage) {
      setMessage('⚠️ Please activate camera or upload an image first');
      return;
    }

    setScanning(true);
    setStatus('scanning');
    setMessage('🔍 Scanning face... Please wait');

    try {
      const employee = await simulateFaceRecognition();
      
      if (employee) {
        setStatus('success');
        setMessage(`✅ Face recognized! Welcome, ${employee.name}`);
        
        // Create user session
        const authData = {
          employeeId: employee.id,
          employeeName: employee.name,
          userRole: employee.role,
          email: employee.email,
          status: 'active',
          token: 'demo-token',
          sessionId: 'sess_' + Date.now(),
          isAdmin: employee.role === 'admin' || employee.role === 'super_admin',
          isManager: employee.role === 'manager',
          isSuperAdmin: employee.role === 'super_admin',
          loginTime: new Date().toISOString()
        };

        // Store in sessionStorage
        sessionStorage.setItem('authToken', authData.token);
        sessionStorage.setItem('authData', JSON.stringify(authData));
        localStorage.setItem('authToken', authData.token);
        localStorage.setItem('authData', JSON.stringify(authData));

        setUser(authData);

        // Stop camera
        stopCamera();

        // Navigate to appropriate dashboard
        setTimeout(() => {
          if (employee.role === 'admin' || employee.role === 'super_admin') {
            navigate('/admin');
          } else if (employee.role === 'manager') {
            navigate('/manager');
          } else {
            navigate('/employee');
          }
        }, 1500);
      } else {
        throw new Error('Face not recognized');
      }
    } catch (error) {
      setStatus('error');
      setMessage('❌ Face not recognized. Please try again.');
      setScanning(false);
    }
  };

  const handleBackToLogin = () => {
    stopCamera();
    navigate('/login');
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setUploadedImage(reader.result);
        setMessage('✓ Image uploaded successfully. Click "Scan Face" to authenticate.');
        setStatus('idle');
      };
      reader.readAsDataURL(file);
    }
  };

  const toggleAuthMode = () => {
    setUseStaticImage(!useStaticImage);
    setUploadedImage(null);
    stopCamera();
    setMessage('');
    setStatus('idle');
  };

  return (
    <div className="face-auth-container">
      <div className="face-auth-box">
        <div className="face-auth-header">
          <h1>🔐 Face Authentication</h1>
          <p>Secure access with facial recognition</p>
        </div>

        <div className="face-auth-content">
          <div className="camera-container">
            <div className={`camera-frame ${status}`}>
              {cameraActive ? (
                <video
                  ref={videoRef}
                  autoPlay
                  playsInline
                  className="camera-video"
                />
              ) : (
                <div className="camera-placeholder">
                  <span className="camera-icon">📷</span>
                  <p>Camera inactive</p>
                  <p className="hint">Click "Activate Camera" to begin</p>
                </div>
              )}
              
              {scanning && (
                <div className="scanning-overlay">
                  <div className="scan-line"></div>
                </div>
              )}
            </div>
          </div>

          <div className="auth-controls">
            {message && (
              <div className={`auth-message ${status}`}>
                {message}
              </div>
            )}

            <div className="button-group">
              {!cameraActive ? (
                <button
                  className="btn-primary"
                  onClick={startCamera}
                  disabled={scanning}
                >
                  📹 Activate Camera
                </button>
              ) : (
                <>
                  <button
                    className="btn-primary"
                    onClick={handleScanFace}
                    disabled={scanning || status === 'success'}
                  >
                    {scanning ? '🔍 Scanning...' : '✓ Scan Face'}
                  </button>
                  <button
                    className="btn-secondary"
                    onClick={stopCamera}
                    disabled={scanning}
                  >
                    Stop Camera
                  </button>
                </>
              )}
            </div>

            <button
              className="btn-link"
              onClick={handleBackToLogin}
              disabled={scanning}
            >
              ← Back to Login
            </button>
          </div>

          <div className="auth-info">
            <p className="info-title">How it works:</p>
            <ol className="info-list">
              <li>Activate your camera</li>
              <li>Position your face in the frame</li>
              <li>Click "Scan Face" to authenticate</li>
              <li>Access granted upon successful recognition</li>
            </ol>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FaceAuth;
